const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const byId=new Map(BANK.map(q=>[q.id,q]));
const equal=(a,b)=>a.length===b.length&&a.every(x=>b.includes(x));
const shuffle=a=>{a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
const key='mln122-study-v1';let storageOK=true;
function read(k,fallback){try{return JSON.parse(localStorage.getItem(k))??fallback}catch{return fallback}}
function write(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{storageOK=false}}
let session=read(key,null),wrongIds=read(key+'-wrong',[]),history=read(key+'-history',[]);
if(!Array.isArray(wrongIds))wrongIds=[];if(!Array.isArray(history))history=[];
if(session&&(!Array.isArray(session.ids)||!session.ids.length||!session.ids.every(x=>byId.has(x))||!session.answers||!Array.isArray(session.checked)||!Array.isArray(session.marked)||!Number.isInteger(session.index)||session.index<0||session.index>=session.ids.length))session=null;
function save(){if(session)write(key,session)}
function home(){
 $('#app').innerHTML=`<section class="hero"><div class="intro"><span class="badge">GÓC HỌC RIÊNG CỦA BẠN</span><h1>Học chắc<br>từng câu<span style="color:#999999">.</span></h1><p>Đọc rõ đề, chọn đáp án, hiểu chỗ sai.<br>Một buổi ôn nhỏ cho MLN122.</p><div class="stats"><div><strong>538</strong><span>Câu hỏi từ PDF</span></div><div><strong>${wrongIds.length}</strong><span>Câu cần ôn lại</span></div><div><strong>${history.length}</strong><span>Bài đã hoàn thành</span></div></div><p class="note">Đáp án theo tài liệu của bạn. 5 câu có dấu hiệu thiếu hoặc mâu thuẫn dữ kiện được bỏ qua mặc định, chưa được hiệu đính về kiến thức.</p></div><form class="panel" id="setup"><h3>Bắt đầu một lượt học</h3><div class="field"><label for="mode">Bạn muốn học thế nào?</label><select id="mode"><option value="practice">Luyện tập · xem đáp án từng câu</option><option value="exam">Kiểm tra · chấm điểm khi nộp</option></select></div><div class="field"><label for="count">Số câu trong lượt này</label><select id="count"><option value="10">10 câu · khởi động</option><option value="20" selected>20 câu · vừa sức</option><option value="50">50 câu · luyện sâu</option><option value="538">Toàn bộ câu hợp lệ</option></select></div><label class="check"><input id="mix" type="checkbox" checked>Đảo thứ tự câu hỏi</label><label class="check"><input id="uncertain" type="checkbox">Bao gồm 5 câu cần đối chiếu PDF</label><button class="primary wide" type="submit">Bắt đầu làm bài →</button>${session&&!session.finished?`<button type="button" class="wide" id="resume" style="margin-top:10px">Tiếp tục bài đang làm (${Object.keys(session.answers).length}/${session.ids.length})</button>`:''}<button type="button" id="wrong" class="wide" style="margin-top:10px" ${wrongIds.length?'':'disabled'}>Ôn lại ${wrongIds.length} câu sai</button><p class="note">Câu nhiều đáp án có ô vuông. Chọn đủ đáp án đúng để được tính điểm.</p></form></section>${history.length?`<div class="panel"><h3>Những lượt học gần đây</h3>${history.slice(-5).reverse().map(h=>`<div class="row spread"><span>${esc(new Date(h.date).toLocaleString('vi-VN'))}</span><strong>${h.correct}/${h.total} câu đúng</strong></div>`).join('')}</div>`:''}`;
 $('#setup').onsubmit=e=>{e.preventDefault();let pool=BANK.filter(q=>$('#uncertain').checked||!q.warning);if($('#mix').checked)pool=shuffle(pool);start(pool.slice(0,Number($('#count').value)).map(q=>q.id),$('#mode').value)};
 if($('#resume'))$('#resume').onclick=()=>renderQuestion();$('#wrong').onclick=()=>start(shuffle(wrongIds.filter(id=>byId.has(id))),'practice');
}
function start(ids,mode){if(!ids.length)return;session={ids,mode,index:0,answers:{},checked:[],marked:[],started:Date.now(),finished:false};save();renderQuestion();window.scrollTo(0,0)}
function qCorrect(q){return equal(session.answers[q.id]||[],q.correct)}
function options(q,reveal=false){const chosen=session.answers[q.id]||[];return q.options.map(o=>`<label class="option ${reveal?(q.correct.includes(o.id)?'good':chosen.includes(o.id)?'bad':''):''}"><input aria-label="${esc(o.id+'. '+o.text)}" type="${q.correct.length>1?'checkbox':'radio'}" name="answer-${q.id}" value="${o.id}" ${chosen.includes(o.id)?'checked':''} ${reveal?'disabled':''}><b>${o.id}.</b><span>${highlight(o.text)}${reveal?(q.correct.includes(o.id)?'<br><span class="verdict">✓ Đáp án đúng</span>':chosen.includes(o.id)?'<br><span class="verdict">✕ Bạn chọn sai</span>':''):''}</span></label>`).join('')}
function answerText(q){return q.correct.map(id=>id+'. '+q.options.find(o=>o.id===id).text).join('\n')}
function feedback(q){return `<div class="feedback ${qCorrect(q)?'':'wrong'}" role="status"><strong>${qCorrect(q)?'Chính xác!':'Chưa đúng — xem lại ý này nhé.'}</strong><p style="white-space:pre-line">${highlight(answerText(q))}</p></div>`}
function notes(q){return q.note?`<details><summary>Ghi chú từ PDF · trang ${q.page}</summary><p class="source">${esc(q.note)}</p></details>`:`<p class="note">Nguồn: PDF, trang ${q.page}.</p>`}
function renderQuestion(){
 const q=byId.get(session.ids[session.index]),reveal=session.checked.includes(q.id);const done=Object.keys(session.answers).length;
 $('#app').innerHTML=`<div class="topline"><div class="row"><span class="badge">${session.mode==='exam'?'KIỂM TRA':'LUYỆN TẬP'}</span><span class="note">Câu ${session.index+1} / ${session.ids.length}</span></div><button id="pause">Lưu & về trang đầu</button></div><div class="layout"><section class="question"><div class="row spread"><span class="eyebrow">MLN122 · Câu gốc ${String(q.id).padStart(3,'0')}</span><button id="mark" aria-pressed="${session.marked.includes(q.id)}">${session.marked.includes(q.id)?'★ Đã đánh dấu':'☆ Đánh dấu'}</button></div><h2 id="qtitle" tabindex="-1">${highlight(q.question)}</h2>${q.warning?`<p class="warning">Cần đối chiếu: ${esc(q.warning)}</p>`:''}<p class="note">${q.correct.length>1?`Chọn ${q.correct.length} đáp án đúng.`:'Chọn một đáp án đúng.'}</p><div role="group" aria-labelledby="qtitle" id="options">${options(q,reveal)}</div>${reveal?feedback(q)+memoryBox(q)+notes(q):''}<div class="actions"><button id="prev" ${session.index===0?'disabled':''}>← Trước</button><div class="row">${session.mode==='practice'&&!reveal?`<button class="primary" id="check" ${(session.answers[q.id]||[]).length?'':'disabled'}>Kiểm tra đáp án</button>`:''}<button id="next" ${session.index===session.ids.length-1?'disabled':''}>Tiếp →</button></div></div></section><aside class="panel sidebar"><div class="row spread"><strong>Tiến độ</strong><small>${done}/${session.ids.length}</small></div><div class="meter"><div style="width:${done/session.ids.length*100}%"></div></div><div class="navgrid">${session.ids.map((id,i)=>`<button data-index="${i}" aria-label="Đến câu ${i+1}" ${i===session.index?'aria-current="step"':''} class="${i===session.index?'current ':''}${session.answers[id]?'answered ':''}${session.marked.includes(id)?'marked':''}">${i+1}</button>`).join('')}</div><p class="note">Nền xám: đã chọn · Gạch dưới: cần xem lại</p><button class="primary wide" id="submit">Nộp bài & xem kết quả</button>${!storageOK?'<p class="warning">Trình duyệt không lưu được tiến độ. Đừng đóng trang trước khi nộp.</p>':''}</aside></div><dialog id="confirm"><h3>Nộp bài này?</h3><p>${done<session.ids.length?`Còn ${session.ids.length-done} câu chưa trả lời. Những câu này sẽ được tính là chưa đúng.`:'Bạn đã trả lời tất cả các câu.'}</p><div class="row"><button id="cancel">Làm tiếp</button><button class="primary" id="finish">Nộp bài</button></div></dialog>`;
 $('#options').onchange=e=>{const selected=e.target.value;const a=[...document.querySelectorAll('#options input:checked')].map(i=>i.value);if(a.length)session.answers[q.id]=a;else delete session.answers[q.id];save();renderQuestion();document.querySelector(`#options input[value="${selected}"]`)?.focus()};
 $('#pause').onclick=()=>{save();home()};$('#mark').onclick=()=>{session.marked=session.marked.includes(q.id)?session.marked.filter(x=>x!==q.id):[...session.marked,q.id];save();renderQuestion()};
 const move=i=>{session.index=i;save();renderQuestion();$('#qtitle').focus();window.scrollTo(0,0)};
 $('#prev').onclick=()=>move(session.index-1);$('#next').onclick=()=>move(session.index+1);document.querySelectorAll('[data-index]').forEach(b=>b.onclick=()=>move(Number(b.dataset.index)));
 if($('#check'))$('#check').onclick=()=>{session.checked.push(q.id);save();renderQuestion()};$('#submit').onclick=()=>$('#confirm').showModal();$('#cancel').onclick=()=>$('#confirm').close();$('#finish').onclick=finish;
}
function finish(){session.finished=true;session.ended=Date.now();const wrong=session.ids.filter(id=>!qCorrect(byId.get(id)));wrongIds=[...new Set([...wrongIds.filter(id=>!session.ids.includes(id)),...wrong])];history.push({date:Date.now(),correct:session.ids.length-wrong.length,total:session.ids.length});history=history.slice(-30);write(key+'-wrong',wrongIds);write(key+'-history',history);save();results();window.scrollTo(0,0)}
function results(onlyWrong=true){const wrong=session.ids.filter(id=>!qCorrect(byId.get(id))),correct=session.ids.length-wrong.length,total=session.ids.length,score=Math.round(correct/total*100);let ids=onlyWrong?wrong:session.ids;
 $('#app').innerHTML=`<section class="panel resulthead"><div><span class="eyebrow">Hoàn thành lượt học</span><h1 style="font-size:34px;letter-spacing:-1px">${score>=80?'Bạn đang nhớ rất tốt.':'Thêm một lượt, chắc hơn một chút.'}</h1><div class="score">${score}<span style="font-size:26px">%</span></div></div><div><h3>${correct}/${total} câu đúng</h3><p>${wrong.length?'Xem lại các câu dưới đây rồi thử thêm một lần. Câu chưa trả lời cũng được đưa vào danh sách ôn lại.':'Tất cả đáp án đều chính xác. Bạn có thể bắt đầu một bộ câu mới.'}</p><div class="row"><button class="primary" id="retry" ${wrong.length?'':'disabled'}>Luyện ${wrong.length} câu chưa đúng</button><button id="home">Bài mới</button></div><p class="note">Điểm theo đáp án PDF · Chọn thiếu hoặc thừa đáp án: chưa đúng.</p></div></section><div class="row spread"><h2>Xem lại bài làm</h2><label class="check"><input type="checkbox" id="filter" ${onlyWrong?'checked':''}>Chỉ hiện câu chưa đúng</label></div><div class="resultlist">${ids.map(id=>{const q=byId.get(id);return `<article class="review"><span class="eyebrow">Câu gốc ${id} · ${qCorrect(q)?'ĐÚNG':'CHƯA ĐÚNG'}</span><h3>${highlight(q.question)}</h3><p class="note">Bạn chọn: ${(session.answers[id]||[]).join(', ')||'Chưa trả lời'}</p>${options(q,true)}${q.warning?`<p class="warning">${esc(q.warning)}</p>`:''}${memoryBox(q)}${notes(q)}</article>`}).join('')||'<div class="panel">Không còn câu sai trong lượt này. Giỏi lắm!</div>'}</div>`;
 $('#home').onclick=home;$('#retry').onclick=()=>start(shuffle(wrong),'practice');$('#filter').onchange=e=>results(e.target.checked);
}
$('#brand').onclick=e=>{e.preventDefault();save();home()};home();
